const repo = process.env.GITHUB_REPO;
const token = process.env.GITHUB_TOKEN;
const language = (process.env.SUMMARY_LANGUAGE || 'EN').toUpperCase();

if (!repo || !repo.includes('/')) {
  throw new Error('Set GITHUB_REPO as owner/repo.');
}
if (!token) {
  throw new Error('Set GITHUB_TOKEN with read access to the repository.');
}

const now = new Date();
const until = now.toISOString();
const sinceDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = sinceDate.toISOString();
const sinceDay = since.slice(0, 10);
const untilDay = until.slice(0, 10);

const headers = {
  Accept: 'application/vnd.github+json',
  Authorization: `Bearer ${token}`,
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-dev-summary'
};

async function getJson(url) {
  const response = await fetch(url, { headers });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`GitHub API ${response.status} for ${url}: ${body}`);
  }
  return response.json();
}

const commitsUrl = `https://api.github.com/repos/${repo}/commits?since=${encodeURIComponent(since)}&until=${encodeURIComponent(until)}&per_page=100`;
const issuesQuery = encodeURIComponent(`repo:${repo} is:issue is:closed closed:${sinceDay}..${untilDay}`);
const prsQuery = encodeURIComponent(`repo:${repo} is:pr is:merged merged:${sinceDay}..${untilDay}`);

const [commits, closedIssuesResult, mergedPrsResult] = await Promise.all([
  getJson(commitsUrl),
  getJson(`https://api.github.com/search/issues?q=${issuesQuery}&per_page=100`),
  getJson(`https://api.github.com/search/issues?q=${prsQuery}&per_page=100`)
]);

const closedIssues = closedIssuesResult.items || [];
const mergedPrs = mergedPrsResult.items || [];

const activity = {
  repo,
  period: { since, until },
  counts: {
    commits: commits.length,
    closedIssues: closedIssues.length,
    mergedPrs: mergedPrs.length
  },
  commits: commits.slice(0, 40).map((commit) => ({
    sha: commit.sha?.slice(0, 7),
    message: commit.commit?.message?.split('\n')[0],
    author: commit.commit?.author?.name,
    url: commit.html_url
  })),
  closedIssues: closedIssues.slice(0, 40).map((issue) => ({
    number: issue.number,
    title: issue.title,
    url: issue.html_url,
    closedAt: issue.closed_at
  })),
  mergedPrs: mergedPrs.slice(0, 40).map((pr) => ({
    number: pr.number,
    title: pr.title,
    url: pr.html_url,
    mergedAt: pr.closed_at
  }))
};

const promptLanguage = language === 'FR' ? 'French' : 'English';
const prompt = `Write a concise weekly narrative development summary in ${promptLanguage} for ${repo}.\n\nRequirements:\n- Start with a one-paragraph executive summary.\n- Include sections: Highlights, Completed Work, Risk or Follow-up, Links.\n- Mention commit, closed issue, and merged PR counts.\n- Prefer user-facing impact over raw commit listing.\n- Keep it under 900 words.\n\nActivity JSON:\n${JSON.stringify(activity, null, 2)}`;

return [{ json: { repo, language, activity, prompt } }];

const text = $json.content?.find((part) => part.type === 'text')?.text || 'Claude returned no text summary.';
const limited = text.length > 1900 ? `${text.slice(0, 1890)}...` : text;
return [{ json: { discordPayload: { content: limited }, summary: text } }];
